{
  "notes": "The provided facts include information about a researcher at the Institute of Informatics Systems (IIS) and the organization itself. The facts are in both English and Russian, and cover roles, types, and participation.",
  "files": {
    "rules/candidate_researcher_at_iis.pl": "#!/usr/bin/perl

use strict;
use warnings;

sub is_candidate_researcher {
    my ($researcher) = @_;

    # Check if the researcher has a role of 'исследователь' (researcher)
    return 1 if $researcher->{role} eq 'исследователь';

    return 0;
}",
    "tests/candidate_researcher_at_iis_tests.pl": "#!/usr/bin/perl

use strict;
use warnings;
use Test::More;

use lib 'rules';
use candidate_researcher_at_iis;

subtest 'Test is_candidate_researcher' => sub {
    my $researcher = { role => 'исследователь' };
    ok(is_candidate_researcher($researcher), 'Researcher with role ",", is a candidate researcher');

    $researcher = { role => 'студент' };
    ok(!is_candidate_researcher($researcher), 'Researcher with role ":", is not a candidate researcher');
};

done_testing();",
    "ui/researcher-at-iis.json": "{
  "title": "Candidate Researcher at IIS",
  "description": "This form allows you to submit information about a candidate researcher at the Institute of Informatics Systems."
}"
  }
}
